@Suite("Labs Panels Extra") struct LabsPanelsExtraTests {
    @Test(arguments: Array(panelCases.keys).sorted()) func panels(_ name: String) {
        let c = panelCases[name]!
        #expect(PanelParsers.parseExtendedLabPanels(c.text, priorBySec: c.prior) == c.lines, "\(name)")
    }

    @Test(arguments: Array(shapeCases.keys).sorted()) func reumShape(_ name: String) {
        let c = shapeCases[name]!
        let reg: ((String) -> String?)? = c.useReg ? { $0 == "SINTETICO1" ? "REG-A" : "" } : nil
        #expect(PanelParsers.reumToSomeShape(c.text, reg) == c.out, "\(name)")
    }

    @Test func sectionKeys() {
        #expect(PanelParsers.LAB_EXTENDED_SECTION_KEYS == ["TIR", "ENDO", "CARD", "FE", "INFL", "INM", "META", "NEF", "NIVEL", "TM", "NUT", "GI", "TOX", "HEPB", "VIRAL", "FEB", "MICRO"])
    }

    @Test func overlay() {
        let recs = [
            PanelOverlayRecord(panelId: "user:zz", sectionKey: "CUST", mode: "num", gates: ["MARCADOR ZZ"], fields: [.init(key: "Zz", labels: ["MARCADOR ZZ"])], updatedAt: 1, updatedBy: "t"),
            PanelOverlayRecord(panelId: "builtin:TIR", sectionKey: "TIR", mode: "num", gates: [#"\bTSH\b"#], fields: [.init(key: "TSHx", labels: ["TSH"])], updatedAt: 1, updatedBy: "t"),
            PanelOverlayRecord(panelId: "user:q", sectionKey: "QQ", mode: "qual", gates: ["PRUEBA (Q)"], fields: [.init(key: "Q", patterns: [#"PRUEBA\s+Q"#])], updatedAt: 1, updatedBy: "t"),
        ]
        let defs = PanelOverlay.applyOverlayToBuiltins(PanelDefs.LAB_EXTENDED_PANEL_DEFS, recs)
        #expect(PanelParsers.parseExtendedLabPanels("QUIMICA CLINICA\nMARCADOR ZZ\nEstudio\t\tResultado\tUnidades\tValor de Referencia\nMARCADOR ZZ\t\n*\n9\nng/mL\t0 - 5\nTSH\nEstudio\t\tResultado\tUnidades\tValor de Referencia\nTSH\t\n*\n5\nuUI/mL\t0.4 - 4.0\nPRUEBA Q\nEstudio\t\tResultado\tUnidades\tValor de Referencia\nPRUEBA Q\t\n2.0\nPOSITIVO\n", priorBySec: [:], defs: defs) == ["TIR\tTSHx 5*", "CUST\tZz 9*", "QQ\tQ pos* (2)"])
    }

    @Test func overlayLww() {
        let a = PanelOverlayRecord(panelId: "p1", sectionKey: "A", updatedAt: 1, updatedBy: "a")
        let b = PanelOverlayRecord(panelId: "p1", sectionKey: "B", updatedAt: 1, updatedBy: "b")
        let c = PanelOverlayRecord(panelId: "p2", sectionKey: "C", updatedAt: 5, updatedBy: "a")
        let d = PanelOverlayRecord(panelId: "p2", sectionKey: "D", updatedAt: 4, updatedBy: "z")
        #expect(PanelOverlay.mergeLabPanelOverlayLww([a, c], [b, d]).map(\.sectionKey) == ["B", "C"])
    }
}
